INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(16011, 1601, 'listening', 'Listening Part 1: Children’s Engineering Workshops', '<div class="ielts-reading-container">
<h2 class="ielts-reading-question-section-heading">
                                            Questions 1-10                                                                                                                                                                                                    
                                                                                                                                    </h2>
                                                                                    
                                                                                <div class="ielts-reading-question-section-content">
                                            <div class="ielts-listening-section-content-wrapper"><p>Complete the notes below.</p>
<p>Write <strong>ONE WORD AND/OR A NUMBER</strong> for each answer.</p>
<p class="ielts-listening-transcript-subhead"><strong><strong>Children’s Engineering Workshops</strong></strong></p>
<p><strong>Tiny Engineers (ages 4-5)</strong></p>
<p>Activities</p>
<ul>
<li>Create a cover for an <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">1</strong><input type="text" data-qnum="1" name="question_1" class="ielts-inline-input" placeholder="[1] javob..." autocomplete="off" spellcheck="false"></span></span> so they can drop it from a height without breaking it.</li>
<li>Take part in a competition to build the tallest <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">2</strong><input type="text" data-qnum="2" name="question_2" class="ielts-inline-input" placeholder="[2] javob..." autocomplete="off" spellcheck="false"></span></span>.</li>
<li>Make a <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">3</strong><input type="text" data-qnum="3" name="question_3" class="ielts-inline-input" placeholder="[3] javob..." autocomplete="off" spellcheck="false"></span></span> powered by a balloon.</li>
</ul>
<p><strong>Junior Engineers (ages 6-8)</strong></p>
<p>Activities:</p>
<ul>
<li>Build model cars, trucks and <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">4</strong><input type="text" data-qnum="4" name="question_4" class="ielts-inline-input" placeholder="[4] javob..." autocomplete="off" spellcheck="false"></span></span> and learn how to program them so they can move.</li>
<li>Take part in a competition to build the longest <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">5</strong><input type="text" data-qnum="5" name="question_5" class="ielts-inline-input" placeholder="[5] javob..." autocomplete="off" spellcheck="false"></span></span> using card and wood.</li>
<li>Create a short <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">6</strong><input type="text" data-qnum="6" name="question_6" class="ielts-inline-input" placeholder="[6] javob..." autocomplete="off" spellcheck="false"></span></span> with special software.</li>
<li>Build, <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">7</strong><input type="text" data-qnum="7" name="question_7" class="ielts-inline-input" placeholder="[7] javob..." autocomplete="off" spellcheck="false"></span></span> and program a humanoid robot.</li>
</ul>
<p>Cost for a five-week block: £50</p>
<p>Held on <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">8</strong><input type="text" data-qnum="8" name="question_8" class="ielts-inline-input" placeholder="[8] javob..." autocomplete="off" spellcheck="false"></span></span> from 10 am to 11 am</p>
<p><strong>Location</strong></p>
<p>Building 10A, <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">9</strong><input type="text" data-qnum="9" name="question_9" class="ielts-inline-input" placeholder="[9] javob..." autocomplete="off" spellcheck="false"></span></span> Industrial Estate, Grasford</p>
<p>Plenty of <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">10</strong><input type="text" data-qnum="10" name="question_10" class="ielts-inline-input" placeholder="[10] javob..." autocomplete="off" spellcheck="false"></span></span> is available.</p>
</div>                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            </div>
                                        </div>
</div>', 'https://ielts-listening-audio.engnovatemedia.com/13183-cambridge-ielts-16-academic-listening-1-audio-1.mp3', 'SARAH: Hello. Children’s Engineering Workshops.
FATHER: Oh hello. I wanted some information about the workshops in the school holidays.
SARAH: Sure.
FATHER: I have two daughters who are interested. The younger one’s Lydia, she’s four – do you take children as young as that?
SARAH: Yes, our Tiny Engineers workshop is for four to five-year-olds.
FATHER: What sorts of activities do they do?
SARAH: All sorts. For example, they work together to design a special cover that goes round an egg, so that when it’s inside they can drop it from a height and it doesn’t break. Well, sometimes it does break but that’s part of the fun!
FATHER: Right. And Lydia loves building things. Is there any opportunity for her to do that?
SARAH: Well, they have a competition to see who can make the highest tower. You’d be amazed how high they can go.
FATHER: Right.
SARAH: But they’re learning all the time as well as having fun. For example, one thing they do is to design and build a car that’s attached to a balloon, and the force of the air in that actually powers the car and makes it move along. They go really fast too.
FATHER: OK, well, all this sounds perfect.
————————
FATHER: Now Carly, that’s my older daughter, has just had her seventh birthday, so presumably she’d be in a different group?
SARAH: Yes, she’d be in the Junior Engineers. That’s for children from six to eight.
FATHER: And do they do the same sorts of activities?
SARAH: Some are the same, but a bit more advanced. So they work out how to build model vehicles, things like cars and trucks, but also how to construct animals using the same sorts of material and technique, and then they learn how they can program them and make them move.
FATHER: So they learn a bit of coding?
SARAH: They do. They pick it up really quickly. We’re there to help if they need it, but they learn from one another too.
FATHER: Right. And do they have competition too?
SARAH: Yes, with the Junior Engineers, it’s to use recycled materials like card and wood to build a bridge, and the longest one gets a prize.
FATHER: That sounds fun. I wouldn’t mind doing that myself!
SARAH: Then they have something a bit different, which is to think up an idea for a five-minute movie and then film it, using special animation software. You’d be amazed what they come up with.
FATHER: And of course, that’s something they can put on their phone and take home to show all their friends.
SARAH: Exactly. And then they also build a robot in the shape of a human, and they decorate it and program it so that it can move its arms and legs.
FATHER: Perfect. So, is it the same price as the Tiny Engineers?
SARAH: It’s just a bit more: £50 for the five weeks.
FATHER: And are the classes on a Monday, too?
SARAH: They used to be, but we found it didn’t give our staff enough time to clear up after the first workshop, so we moved them to Wednesdays. The classes are held in the morning from ten to eleven.
FATHER: OK. That’s better for me actually. And what about the location? Where exactly are the workshops held?
SARAH: They’re in building 10A – there’s a big sign on the door, you can’t miss it, and that’s in Fradstone Industrial Estate.
FATHER: Sorry?
SARAH: Fradstone – that’s F-R-A-D-S-T-O-N-E.
FATHER: And that’s in Grasford, isn’t it?
SARAH: Yes, up past the station.
FATHER: And will I have any parking problems there?
SARAH: No, there’s always plenty available. So would you like to enrol Lydia and Carly now?
FATHER: OK.
SARAH: So can I have your full name …', 1)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, instructions = EXCLUDED.instructions, audio_url = EXCLUDED.audio_url, passage_text = EXCLUDED.passage_text;

