ell"><input data-qnum="17" type="radio" name="question_17" id="ielts_listening_answer_13123_3_7" value="H"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input data-qnum="17" type="radio" name="question_17" id="ielts_listening_answer_13123_3_8" value="I"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input data-qnum="17" type="radio" name="question_17" id="ielts_listening_answer_13123_3_9" value="J"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-listening-question-item"><td class="ielts-listening-matching-question-cell"><strong id="ielts-listening-question-number-18" class="ielts-q-badge">18</strong> <span>meeting room</span></td>
