ell"><input data-qnum="20" type="radio" name="question_20" id="ielts_listening_answer_13123_6_7" value="H"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input data-qnum="20" type="radio" name="question_20" id="ielts_listening_answer_13123_6_8" value="I"></td>                                                                                                            <td class="ielts-listening-matching-option-cell"><input data-qnum="20" type="radio" name="question_20" id="ielts_listening_answer_13123_6_9" value="J"></td></tr></tbody></table>                                                                                                                                                                                        </div>
